namespace Game_Catalog.Models
{
    /// <summary> Represents a game genre from the reference table. </summary>
    public class Genre
    {
        /// <summary> Unique identifier of the genre. Generated by the database. </summary>
        public int GenreId { get; set; }

        private string _genreName = string.Empty;
        /// <summary> Name of the genre. </summary>
        public string GenreName
        {
            get => _genreName;
            set => _genreName = value ?? string.Empty;
        }

        private string _genreDescription = string.Empty;
        /// <summary> Optional description of the genre. Empty means no description. </summary>
        public string GenreDescription
        {
            get => _genreDescription;
            set => _genreDescription = value ?? string.Empty;
        }
    }
}